parameters.jsCode:
const invoiceId = Number($('invoice/items/edit-with-reallocation').first().json.body.invoice_id);
const newTotal = Number($('Recalculate Invoice Total4').first().json.total);

const paymentRows = $('Get Payment Allocations').all().map((i) => i.json);
const creditRows = $('Get Invoice Allocations').all().map((i) => i.json);

// FIFO por fecha de aplicación original; empate por id ascendente.
const pool = [...paymentRows, ...creditRows].sort((a, b) => {
  const ta = new Date(a.created_at).getTime();
  const tb = new Date(b.created_at).getTime();
  if (ta !== tb) return ta - tb;
  return Number(a.id) - Number(b.id);
});

const poolTotal = pool.reduce((sum, row) => sum + Number(row.amount), 0);

let remaining = newTotal;
const toReinsert = [];

for (const row of pool) {
  if (remaining <= 0.0001) break;
  const rowAmount = Number(row.amount);
  const take = Math.min(rowAmount, remaining);
  if (take <= 0.0001) continue;

  // Proporción del monto original que efectivamente entra — se aplica también
  // al target_amount para no perder la relación de tipo de cambio original.
  const ratio = take / rowAmount;

  toReinsert.push({
    invoice_id: invoiceId,
    origin_type: row.origin_type,
    origin_id: row.origin_id,
    amount: Math.round(take * 100) / 100,
    allocated_currency: row.allocated_currency,
    target_amount: Math.round(Number(row.target_amount) * ratio * 100) / 100,
    exchange_rate: row.exchange_rate,
    new_total: newTotal,
    pool_total: Math.round(poolTotal * 100) / 100,
  });

  remaining = Math.round((remaining - take) * 100) / 100;
}

const reinsertedTotal = toReinsert.reduce((s, r) => s + r.amount, 0);
const releasedAmount = Math.round((poolTotal - reinsertedTotal) * 100) / 100;
for (const item of toReinsert) item.released_amount = releasedAmount;

if (toReinsert.length === 0) {
  // No había nada que reasignar (o el nuevo total es 0) — igual se emite un
  // item "vacío" con la metadata necesaria para armar la respuesta final; el
  // loop de más abajo lo hace pasar sin insertar nada.
  return [{
    json: {
      invoice_id: invoiceId,
      new_total: newTotal,
      pool_total: Math.round(poolTotal * 100) / 100,
      released_amount: releasedAmount,
      _empty: true,
    },
  }];
}

return toReinsert.map((item) => ({ json: item }));

const source = $('Merge & Reallocate FIFO').all().map((i) => i.json);
const meta = source[0] || {};

const grouped = {};
for (const item of source) {
  if (item._empty) continue;
  const key = item.origin_type + ':' + item.origin_id;
  if (!grouped[key]) grouped[key] = { origin_type: item.origin_type, origin_id: item.origin_id, amount: 0 };
  grouped[key].amount = Math.round((grouped[key].amount + Number(item.amount)) * 100) / 100;
}

return [{
  json: {
    success: true,
    invoice_id: meta.invoice_id,
    new_total: meta.new_total,
    reallocated: Object.values(grouped),
    released_amount: meta.released_amount,
    code: 200,
  },
}];

const body = $('payment/edit-with-reallocation').first().json.body;
const current = $('Get payment1').first().json;

const currentAmount = Math.abs(Number(current.amount));
const newAmount = Math.abs(Number(body.amount));
const methodChanged = String(body.payment_method_id) !== String(current.payment_method_id);
const amountChanged = Math.abs(newAmount - currentAmount) > 0.0001;

return [{
  json: {
    payment_id: current.id,
    needs_cash_check: methodChanged || amountChanged,
    method_changed: methodChanged,
    amount_changed: amountChanged,
    new_payment_method_id: body.payment_method_id,
    new_amount: newAmount,
    new_payment_date: body.payment_date,
    new_notes: body.notes || '',
    new_is_historical: !!body.is_historical,
  },
}];

const payment = $('Get payment1').first().json;
const activeSessionId = $json.data ? $json.data.id : null;
const hasOwnSession = payment.cash_session_id !== null && payment.cash_session_id !== undefined;
// Un pago que nunca tuvo sesión de caja (histórico) no tiene nada que proteger;
// uno que sí tuvo, solo se puede editar si esa sesión sigue siendo la activa.
const sessionOk = !hasOwnSession || (activeSessionId !== null && Number(activeSessionId) === Number(payment.cash_session_id));

return [{ json: { session_ok: sessionOk, active_session_id: activeSessionId } }];

const paymentId = Number($('Get payment1').first().json.id);
const newAmount = Math.abs(Number($('Detectar cambios').first().json.new_amount));

const rows = $('Get Payment Allocations (Pago)').all().map((i) => i.json);
const pool = [...rows].sort((a, b) => {
  const ta = new Date(a.created_at).getTime();
  const tb = new Date(b.created_at).getTime();
  if (ta !== tb) return ta - tb;
  return Number(a.id) - Number(b.id);
});

const poolTotal = pool.reduce((sum, row) => sum + Number(row.amount), 0);

let remaining = newAmount;
const toReinsert = [];

for (const row of pool) {
  if (remaining <= 0.0001) break;
  const rowAmount = Number(row.amount);
  const take = Math.min(rowAmount, remaining);
  if (take <= 0.0001) continue;

  // Misma lógica que el Flujo A: se preserva la proporción del tipo de
  // cambio / target_amount original, no se recalcula de nuevo.
  const ratio = take / rowAmount;

  toReinsert.push({
    payment_id: paymentId,
    invoice_id: row.invoice_id,
    amount: Math.round(take * 100) / 100,
    allocated_currency: row.allocated_currency,
    target_amount: Math.round(Number(row.target_amount) * ratio * 100) / 100,
    exchange_rate: row.exchange_rate,
  });

  remaining = Math.round((remaining - take) * 100) / 100;
}

const reinsertedTotal = toReinsert.reduce((s, r) => s + r.amount, 0);
const releasedAmount = Math.round((poolTotal - reinsertedTotal) * 100) / 100;

if (toReinsert.length === 0) {
  return [{
    json: {
      payment_id: paymentId,
      new_amount: newAmount,
      pool_total: Math.round(poolTotal * 100) / 100,
      released_amount: releasedAmount,
      _empty: true,
    },
  }];
}

return toReinsert.map((item) => ({
  json: { ...item, new_amount: newAmount, released_amount: releasedAmount },
}));

const source = $('Reallocate FIFO (Pago)').all().map((i) => i.json);
const meta = source[0] || {};
const reallocated = source.filter((i) => !i._empty).map((i) => ({ invoice_id: i.invoice_id, amount: i.amount }));

return [{
  json: {
    success: true,
    payment_id: meta.payment_id,
    new_amount: meta.new_amount,
    reallocated,
    released_amount: meta.released_amount,
    code: 200,
  },
}];

